function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const isYes = function (x) { return s(x).toLowerCase() === 'yes'; };
const num = function (x) { const n = parseFloat(s(x).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
const trk = $('Read Deal Tracker').all().map(function (i) { return i.json; });
const invRaw = $('Read INVESTORS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
function parseDate(v) { const t = s(v); if (!t) { return ''; }
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) { return m[1] + '-' + m[2] + '-' + m[3]; }
  m = t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/); if (m) { let y = +m[3]; if (y < 100) { y += 2000; } return y + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[1]).slice(-2); }
  const d = new Date(t); return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10); }
const inv = {};
for (const r of invRaw) { const k = nz(r.investor); if (!k) { continue; } const x = inv[k] || { name: s(r.investor), contact: '', email: '', dnc: false, rows: 0 };
  x.rows++; if (!x.contact && s(r.contact_person)) { x.contact = s(r.contact_person); } if (!x.email && s(r.email)) { x.email = s(r.email); } if (isYes(r.do_not_contact)) { x.dnc = true; } inv[k] = x; }
const agg = {};
for (const p of pipe) { const k = nz(p.investor); if (!k) { continue; }
  const a = agg[k] || (agg[k] = { investor: s(p.investor), sent: 0, queued: 0, paused_unsent: 0, responses: 0, response_values: {}, passes: 0, meetings: 0, fu1: 0, fu2: 0, fu3: 0, first_sent: '', last_sent: '', last_contact: '', startups_sent: [] });
  const sent = isYes(p.deal_shared);
  if (!sent) { if (isYes(p.pause)) { a.paused_unsent++; } else { a.queued++; } continue; }
  a.sent++; a.startups_sent.push(s(p.startup));
  const d = parseDate(p.date_shared); if (d) { if (!a.first_sent || d < a.first_sent) { a.first_sent = d; } if (!a.last_sent || d > a.last_sent) { a.last_sent = d; } }
  const lc = parseDate(p.last_contact); if (lc && (!a.last_contact || lc > a.last_contact)) { a.last_contact = lc; }
  if (isYes(p.fu1_done)) { a.fu1++; } if (isYes(p.fu2_done)) { a.fu2++; } if (isYes(p.fu3_done)) { a.fu3++; }
  const resp = s(p.investor_response); if (resp) { a.responses++; a.response_values[resp] = (a.response_values[resp] || 0) + 1; }
  if (s(p.pass_reason) || /pass/i.test(resp)) { a.passes++; }
  if (isYes(p.meeting_scheduled) || s(p.meeting_date) || num(p.meetings_held) > 0 || s(p.last_meeting_date) || s(p.meeting_outcome) || num(p.committed_cr) > 0) { a.meetings++; } }
// tracker: every column, so engagement columns can be judged offline
const tcols = Object.keys(trk[0] || {});
let cInv = null; for (const c of tcols) { const l = c.toLowerCase(); if (!cInv && (l.indexOf('investor') >= 0 || l.indexOf('vc name') >= 0)) { cInv = c; } }
const tracker = trk.map(function (r) { const o = {}; for (const c of tcols) { const v = s(r[c]); if (v) { o[c] = v.slice(0, 300); } } return o; });
const out = Object.keys(agg).map(function (k) { const a = agg[k]; const i = inv[k] || {}; a.key = k; a.in_investors = !!inv[k]; a.contact = i.contact || ''; a.email = i.email || ''; a.dnc = !!i.dnc; a.startups_sent = a.startups_sent.join(', '); return a; });
return [{ json: { pipeline_rows: pipe.length, tracker_rows: trk.length, tracker_investor_col: cInv, tracker_cols: tcols, investors: out, tracker: tracker } }];
